/**
 * Build the shipped halves. Run with `node build.ts`.
 *
 * Three outputs:
 * - `library.generated.ts` holds the OpenUI library schema and prompt, read from
 *   `@openuidev/react-ui` at build time. The host half needs the schema to
 *   validate and the prompt to hand the model, but it must not import React or
 *   the browser library, so this file is generated before anything compiles.
 * - `lib/host.js` is the Node half; its dependencies stay external.
 * - `lib/client.js` is the browser artifact: one closure factory that resolves
 *   React from the shell module table, as the Harness client loader expects.
 */
import { build } from 'esbuild'
import { mkdir, readFile, writeFile } from 'node:fs/promises'
import { openuiChatLibrary, openuiChatPromptOptions } from '@openuidev/react-ui/genui-lib'

const ID = 'dsh-openui-widget'

await mkdir('.build', { recursive: true })
await mkdir('lib', { recursive: true })

/** Write the library data both halves compile against. */
function emitLibraryData(root: string | undefined, schema: unknown, prompt: string): string {
  return `/**
 * Generated by build.ts from @openuidev/react-ui. Do not edit.
 * Regenerate with \`npm run bundle\`.
 */

/** Root component a program must start with. */
export const LIBRARY_ROOT: string = ${JSON.stringify(root ?? 'Card')}

/** Component vocabulary the host validates against. */
export const LIBRARY_SCHEMA: unknown = ${JSON.stringify(schema)}

/** The model-facing guide: syntax, rules, components, and examples. */
export const LIBRARY_PROMPT: string = ${JSON.stringify(prompt)}
`
}

const schema = openuiChatLibrary.toJSONSchema()
const prompt = openuiChatLibrary.prompt(openuiChatPromptOptions)
const source = emitLibraryData(openuiChatLibrary.root, schema, prompt)
await writeFile('library.generated.ts', source)
console.log(`library.generated.ts ${(source.length / 1024).toFixed(1)} KiB (prompt ${(prompt.length / 1024).toFixed(1)} KiB)`)

/* `--data-only` stops after the capture, which is all a typecheck needs. */
if (process.argv.includes('--data-only')) process.exit(0)

await build({
  entryPoints: ['index.ts'],
  bundle: true,
  format: 'esm',
  platform: 'node',
  target: 'node20',
  packages: 'external',
  outfile: 'lib/host.js',
})

await build({
  entryPoints: ['client/index.ts'],
  bundle: true,
  format: 'cjs',
  platform: 'browser',
  target: 'es2022',
  external: ['react', 'react-dom', 'react/jsx-runtime'],
  loader: { '.css': 'text' },
  define: { 'process.env.NODE_ENV': '"production"' },
  minify: true,
  outfile: '.build/client.cjs',
})

const body = await readFile('.build/client.cjs', 'utf8')
const artifact = `window.__ModuleLoader__.load({
  id: ${JSON.stringify(ID)},
  factory(require) {
    var module = { exports: {} };
    var exports = module.exports;
${body}
    return module.exports;
  },
});
`
await writeFile('lib/client.js', artifact)

const host = await readFile('lib/host.js', 'utf8')
console.log(`lib/host.js ${(host.length / 1024).toFixed(1)} KiB`)
console.log(`lib/client.js ${(artifact.length / 1024).toFixed(1)} KiB`)
